# Conversation extraction: split transcript into speaker turns, detect Q/A pairs.
text = """AMY: What time is it?\nBOB: Nearly noon.\nAMY: Thanks!""".replace("\\n", "\n")
import re
turns = []
for line in text.splitlines():
    m = re.match(r"\s*([A-Za-z][A-Za-z0-9_ ]{0,20}):\s*(.*)", line)
    if m: turns.append({"speaker": m.group(1).strip(), "text": m.group(2).strip()})
print(f"{len(turns)} turns:")
qa = []
for t in turns:
    print(f"  [{t['speaker']}] {t['text'][:50]}")
for a, b in zip(turns, turns[1:]):
    if a["text"].endswith("?") and not b["text"].endswith("?"):
        qa.append((a, b))
print(f"Q/A pairs: {len(qa)}")
for q, an in qa:
    print(f"  Q({q['speaker']}): {q['text'][:40]} -> A({an['speaker']}): {an['text'][:40]}")

